import React from 'react';
import './QuestionList.css';

function QuestionList() {
  return (
    <div className="question-list-container">
      <h2>Întrebări</h2>
      <div className="question-item">
        <h3>Exemplu întrebare 1</h3>
        <p>Autor: Ana</p>
        <p>Etichete: <span className="tag">java</span> <span className="tag">oop</span></p>
      </div>

      <div className="question-item">
        <h3>Exemplu întrebare 2</h3>
        <p>Autor: Ion</p>
        <p>Etichete: <span className="tag">react</span> <span className="tag">frontend</span></p>
      </div>
    </div>
  );
}

export default QuestionList;
